/* MotoVault design reference v1. Browser-local sample interactions, never production storage. */
const KEY = 'motovault-app-ui-v2.0';
const DEMO_TODAY = '2026-10-14';
const seed = () => ({language:'bn',theme:'light',brand:'yamaha',model:'MT-15 V2',odometer:12450,baselineKnown:true,reminders:false,
  logs:[{id:'l1',kind:'service',date:'2026-10-10',odo:12300,cost:950,component:'oil',note:''},{id:'l2',kind:'fuel',date:'2026-10-07',odo:12200,cost:650,litres:5,full:true,note:''}],
  documents:[{id:'d1',type:'tax',number:'SAMPLE-TAX-01',holder:'নমুনা ব্যবহারকারী',expiry:'2026-10-21',issued:'2025-10-21',sample:true},{id:'d2',type:'registration',number:'SAMPLE-REG-01',holder:'নমুনা ব্যবহারকারী',expiry:'',issued:'2024-04-15',sample:true}],
  schedules:[{id:'oil',km:2000,days:90,lastOdo:12300,lastDate:'2026-10-10',known:true},{id:'chain',km:500,days:30,lastOdo:12000,lastDate:'2026-09-25',known:false}]});
let state; try { state=JSON.parse(localStorage.getItem(KEY))||seed(); } catch { state=seed(); }
let route='garage', draft=null, filePreview=null, selectedDoc='d1', editingLog=null, selectedComponent='oil', filter='all', failNext=false, largeText=false, setupDraft={brand:state.brand,model:state.model,odometer:String(state.odometer)}, dirty=false;
const screen=document.getElementById('screen');
document.body?.classList.toggle('app-only',new URLSearchParams(location.search||'').get('mode')==='app');
const T=(bn,en)=>state.language==='bn'?bn:en;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=value=>new Intl.NumberFormat(state.language==='bn'?'bn-BD':'en-BD',{maximumFractionDigits:2}).format(value);
const parseNumber=value=>{let normalized=String(value).replace(/[০-৯]/g,c=>'০১২৩৪৫৬৭৮৯'.indexOf(c)).trim();if(normalized.includes(',')&&!/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(normalized))return NaN;normalized=normalized.replace(/,/g,'');return /^\d+(\.\d+)?$/.test(normalized)?Number(normalized):NaN;};
const date=value=>value?new Intl.DateTimeFormat(state.language==='bn'?'bn-BD':'en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z')):T('মেয়াদ দেওয়া নেই','No expiry entered');
const days=value=>Math.ceil((Date.parse(value+'T12:00:00Z')-Date.parse(DEMO_TODAY+'T12:00:00Z'))/86400000);
const docName=type=>({tax:T('ট্যাক্স টোকেন','Tax token'),registration:T('রেজিস্ট্রেশনের কাগজ','Registration document'),licence:T('ড্রাইভিং লাইসেন্স','Driving licence'),insurance:T('ইনস্যুরেন্স','Insurance')})[type]||type;
const componentName=id=>id==='chain'?T('চেইন পরিষ্কার ও লুব','Chain cleaning & lubrication'):id==='oil'?T('ইঞ্জিন অয়েল','Engine oil'):'';
const money=value=>`৳ ${n(value)}`;
const badge=(text,kind='neutral')=>`<span class="badge ${kind}">${text}</span>`;
const notice=(title,copy,kind='',action='')=>`<div class="notice ${kind}"><span class="notice-icon" aria-hidden="true">${kind==='error'?'!':kind==='success'?'✓':kind==='warning'?'!':'i'}</span><div class="grow"><strong>${title}</strong><p>${copy}</p>${action}</div></div>`;
const btn=(label,destination,kind='')=>`<button type="button" class="button ${kind}" data-route="${destination}">${label}</button>`;
const head=(title,copy='',back='')=>`${back?`<button class="back" data-route="${back}">← ${T('ফিরে যান','Back')}</button>`:''}<div class="page-head"><div><h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</div></div>`;
const field=(id,label,value='',type='text',help='',required=true)=>`<div class="field"><label for="${id}">${label}${required?'':` <span class="meta">(${T('চাইলে','optional')})</span>`}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='text'&&/odo|cost|litres|interval|baseline/.test(id)?'inputmode="decimal"':''} aria-describedby="${id}-help ${id}-error"><span id="${id}-help" class="help">${help}</span><span id="${id}-error" class="field-error" role="alert"></span></div>`;
const select=(id,label,options,value)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${options.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></div>`;
const formError=()=>'<div id="form-error" role="alert" hidden></div>';
const check=(id,label,checked=false,help='')=>`<div class="check-row"><input id="${id}" name="${id}" type="checkbox" ${checked?'checked':''}><label for="${id}">${label}${help?`<small>${help}</small>`:''}</label></div>`;
let imageFor=model=>model.includes('Duke')?'assets/duke.jpg':model.includes('250NK')?'assets/250nk.png':model.includes('R15')?'assets/r15.png':'assets/mt15.png';
const screens={
  welcome:['S01','Welcome','Language and first value. No maintenance knowledge required.'],
  bike:['S02','Choose a bike','Recognizable models, manual fallback and one shared brand system.'],
  setup:['S03','Ownership setup','Minimum useful setup. Unknown service history is an honest state.'],
  garage:['S04','Garage','Urgency and quick logging lead. Motorcycle identity supports the task.'],
  fuel:['S05','Fuel entry','Date selection, either digit script and inline validation.'],
  service:['S06','Service entry','Logging and odometer update form one action.'],
  components:['S07','Maintenance','Schedule estimates are explained, never presented as measured condition.'],
  schedule:['S08','Schedule setup','Owners can supply a known baseline without inventing missing history.'],
  history:['S09','Records','Persistent filters, correction and reachable logging actions.'],
  documents:['S10','Documents','Readable document list. Expiry and retrieval are visible without card overlap.'],
  capture:['S11','Import document','Explicit exit and protected drafts. Browser upload stands in for native import.'],
  review:['S12','Review document','Originals are preserved. Enter or correct details before confirmation.'],
  document:['S13','Document details','Original and metadata are clearly distinguished.'],
  inspection:['S14','Show documents','Simple high-readability view; light presentation only for this task.'],
  passport:['S15','Service summary','Review what will leave the device. A summary is not a backup or official proof.'],
  settings:['S16','Settings','Language, theme and privacy explained in one predictable location.'],
  reminders:['S17','Reminders','Opt-in, clear timing and permission denial recovery.'],
  recovery:['S18','Recovery','Restoration errors never masquerade as normal onboarding.'],
  odometer:['S19','Update reading','Quick correction with consequences explained.'],
  saved:['S20','Saved','Clear success and a natural next step.'],
  camera:['S21','Camera preview','Simulated preview. Uncertain quality checks warn, but do not block a ready shutter.'],
  crop:['S22','Adjust preview','Accessible edge controls accompany cropping. Original remains unchanged; preview geometry is a design demonstration.'],
  pages:['S23','Document pages','Front/back and multiple-page ordering use one explicit page-management surface.'],
  cameraDenied:['S24','Camera permission','Permission denial has two useful exits: import or settings guidance.'],
  original:['S25','Original viewer','Keep original pages distinct from metadata and adjusted previews.']
};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{return false;}}
function commit(next){if(failNext){failNext=false;showError('form-error',T('সেভ করা যায়নি। আগের তথ্য বদলায়নি। আবার চেষ্টা করুন।','Could not save. Previous records are unchanged. Try again.'));return false;}const previous=state;state=next;if(!persist()){state=previous;showError('form-error',T('এই ব্রাউজারে সেভ করা যাচ্ছে না। তথ্য কপি করে রাখুন, তারপর আবার চেষ্টা করুন।','Browser storage is unavailable. Copy your entries, then try again.'));return false;}dirty=false;return true;}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.hidden=true,3500);}
function showError(id,message){const el=document.getElementById(id);if(!el)return;el.textContent=message;el.hidden=false;if(id==='form-error')el.className='save-error';else document.getElementById(id.replace('-error',''))?.setAttribute('aria-invalid','true');}
function clearErrors(){screen.querySelectorAll('.field-error').forEach(el=>el.textContent='');screen.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));const el=document.getElementById('form-error');if(el){el.hidden=true;el.textContent='';}}
async function confirmAction(title,copy){const dialog=document.getElementById('confirm-dialog');document.getElementById('confirm-title').textContent=title;document.getElementById('confirm-copy').textContent=copy;document.getElementById('confirm-cancel').textContent=T('থাক, ফিরে যাই','Keep working');document.getElementById('confirm-ok').textContent=T('হ্যাঁ, এগিয়ে যাই','Continue');dialog.returnValue='cancel';dialog.showModal();return new Promise(resolve=>dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true}));}
let permittedHash=null,ignoreHash=false;
const documentFlow=new Set(['capture','camera','crop','review','pages','cameraDenied']);
function syncReviewDraft(){if(route!=='review'||!document.getElementById('review-form'))return;draft={...draft,number:document.getElementById('doc-number').value,holder:document.getElementById('doc-holder').value,issued:document.getElementById('doc-issued').value,expiry:document.getElementById('doc-expiry').value,confirmed:document.getElementById('doc-confirm').checked};}
async function navigate(next){syncReviewDraft();if(!screens[next])next='garage';if(dirty&&next!==route&&!(documentFlow.has(route)&&documentFlow.has(next))){const leave=await confirmAction(T('লেখা তথ্য বাদ দেবেন?','Discard your entries?'),T('এখন বের হলে এই ফর্মের সেভ না করা তথ্য থাকবে না।','Leaving now will discard unsaved form entries.'));if(!leave)return;dirty=false;draft=null;}permittedHash=next;location.hash=next;if(route===next)render();}
function docStatus(d){if(!d.expiry)return badge(T('মেয়াদ দেওয়া নেই','No expiry entered'));const left=days(d.expiry);return left<0?badge(T('মেয়াদ শেষ','Expired'),'error'):left<=30?badge(T(`আর ${n(left)} দিন`,`${n(left)} days left`),'warning'):badge(T('মেয়াদ আছে','Within entered expiry'),'good');}
function bikeCard(){return `<div class="card bike-card"><img class="bike-thumb" src="${imageFor(state.model)}" alt="${esc(state.model)}"><div class="grow"><strong>${esc(state.model)}</strong><span class="meta">${T('আপনার বাইক','Your motorcycle')} · ${n(state.odometer)} ${T('কিমি','km')}</span><button class="text-link" data-route="odometer">${T('রিডিং বদলান','Update reading')} →</button></div></div>`;}
function sampleDocument(d){if(d.upload?.startsWith('data:image/'))return `<img class="document-media" src="${d.upload}" alt="${T('আপনার বাছাই করা কাগজের ছবি','Your selected document image')}">`;return `<div class="document-preview"><span class="sample-stamp">${d.sample?'SAMPLE · NOT A REAL DOCUMENT':T('বাছাই করা ফাইল','SELECTED FILE')}</span><h3>${docName(d.type||'tax')}</h3><p>${T('নম্বর','Number')}: ${esc(d.number||'SAMPLE-01')}</p><p>${T('নাম','Name')}: ${esc(d.holder||T('নমুনা ব্যবহারকারী','Sample owner'))}</p><p>${d.fileName?esc(d.fileName):T('এটি ডিজাইন দেখানোর নমুনা। আসল কাগজ নয়।','Design sample only. Not a real credential.')}</p></div>`;}
function render(){route=screens[location.hash.slice(1)]?location.hash.slice(1):'garage';if(route==='review'&&!draft)draft={type:'tax',sample:true};document.documentElement.lang=state.language;document.documentElement.dataset.theme=state.theme;document.getElementById('app-shell').classList.toggle('inspection',route==='inspection');document.getElementById('app-shell').classList.toggle('large-text',largeText);document.getElementById('language-toggle').textContent=T('English','বাংলা');document.getElementById('route-label').textContent=screens[route][0]+' · '+screens[route][1];document.getElementById('annotation-title').textContent=screens[route][1];document.getElementById('annotation-copy').textContent=screens[route][2];document.getElementById('screen-index').innerHTML=Object.entries(screens).map(([key,[id,label]])=>`<a href="#${key}" class="index-link ${route===key?'active':''}" ${route===key?'aria-current="page"':''}><span>${id}</span>${label}</a>`).join('');
  const section=['documents','capture','review','document','inspection','reminders','camera','crop','pages','cameraDenied','original'].includes(route)?'documents':['history','passport'].includes(route)?'history':'garage';
  document.getElementById('bottom-nav').innerHTML=[['garage','⌂',T('আমার বাইক','My bike')],['documents','▤',T('কাগজপত্র','Documents')],['history','◷',T('রেকর্ড','Records')]].map(([r,i,label])=>`<a href="#${r}" ${r===section?'aria-current="page"':''} class="${r===section?'active':''}"><span class="nav-symbol" aria-hidden="true">${i}</span>${label}</a>`).join('');document.getElementById('bottom-nav').hidden=['welcome','bike','setup','capture','review','inspection','recovery','saved','camera','crop'].includes(route);
  const renderer=views[route];screen.innerHTML=renderer();screen.dataset.screenId=screens[route][0];if(route==='capture'){const camera=document.createElement('button');camera.type='button';camera.className='button secondary full';camera.dataset.route='camera';camera.textContent=T('ক্যামেরায় ছবি তুলুন','Take a photo');screen.querySelector('form').prepend(camera);}if(route==='review'){const crop=document.createElement('button');crop.type='button';crop.className='button secondary';crop.dataset.route='crop';crop.textContent=T('কাগজের সীমানা ঠিক করুন','Adjust document edges');screen.querySelector('.review-tools').append(crop);}bindScreen();}
const views={
 welcome:()=>`<div class="eyebrow">${T('বাইক আপনার, যত্নের সঙ্গী আমরা','Your bike. A companion for its care.')}</div>${head(T('বাইকের সব হিসাব,<br>এক জায়গায়।','Your motorcycle,<br>all in one place.'),T('সার্ভিস, তেল ভরার হিসাব আর কাগজপত্র। সহজে রাখুন, দরকারে খুঁজে পান।','Service, fuel records and documents. Easy to keep, easy to find.'))}<img class="model-photo" src="assets/mt15.png" alt="Yamaha MT-15 V2"><div class="stack"><div class="row"><span class="record-icon">✓</span><span>${T('কখন কী করতে হবে, দেখুন','See what needs attention')}</span></div><div class="row"><span class="record-icon">▤</span><span>${T('দরকারে কাগজপত্র দেখান','Show documents when needed')}</span></div></div>${btn(T('আমার বাইক যোগ করি','Add my motorcycle'),'bike','full')}<p class="help">${T('শুরু করতে আগের সার্ভিসের সব তথ্য লাগবে না।','You do not need your full service history to start.')}</p><div class="prototype-label">${T('এটি নমুনা প্রোটোটাইপ। আসল তথ্য দেবেন না।','Sample prototype. Please do not enter real personal data.')}</div>`,
 bike:()=>`<div class="step-dots"><span class="done"></span><span></span></div>${head(T('আপনার বাইক কোনটি?','What do you ride?'),T('ব্র্যান্ড বেছে মডেলটি খুঁজে নিন।','Choose a brand and find your model.'),'welcome')}<div class="brand-grid">${['Yamaha','KTM','CFMOTO','Honda','Suzuki','Bajaj','TVS','Hero','Royal Enfield'].map(b=>`<button class="choice" data-brand="${b.toLowerCase()}" aria-pressed="${setupDraft.brand===b.toLowerCase()}">${b}</button>`).join('')}</div>${field('model-search',T('মডেল খুঁজুন','Find model'),'','search',T('না পেলে নিচে নিজেই নাম লিখতে পারবেন।','You can enter the name if it is not listed.'),false)}<div id="model-results" class="stack">${modelChoices()}</div><details><summary>${T('আমার মডেলটি নেই','My model is not listed')}</summary>${field('manual-model',T('মডেলের নাম','Model name'),'','text','',false)}<button class="text-link" id="use-manual">${T('এই নাম ব্যবহার করুন','Use this name')}</button></details>${btn(T('এগিয়ে যাই','Continue'),'setup','full')}`,
 setup:()=>`<div class="step-dots"><span class="done"></span><span class="done"></span></div>${head(T('শুরু করি সহজভাবে','A simple start'),T('এখন শুধু মিটারের রিডিং দিন। বাকি তথ্য পরে যোগ করা যাবে।','Start with your current meter reading. Add other details later.'),'bike')}<div class="card bike-card"><img class="bike-thumb" src="${imageFor(setupDraft.model)}" alt="${esc(setupDraft.model)}"><strong>${esc(setupDraft.model)}</strong></div><form id="setup-form" class="form" novalidate>${field('setup-odo',T('মিটারের রিডিং (কিমি)','Meter reading (km)'),setupDraft.odometer,'text',T('মিটারে এখন যত কিমি দেখাচ্ছে। বাংলা বা English সংখ্যা লিখতে পারবেন।','Use the reading on your meter. Bangla or English digits both work.'))}${notice(T('আগের সার্ভিসের তথ্য জানেন না?','Not sure about previous service?'),T('সমস্যা নেই। সার্ভিসের তথ্য যোগ না করা পর্যন্ত আমরা সময়ের আন্দাজ দেখাব না।','That is okay. We will not estimate service timing until you add a baseline.'))}${formError()}<button class="button full" type="submit">${T('আমার বাইক তৈরি করুন','Create my garage')}</button></form>`,
 garage:()=>`${head(T('আমার বাইক','My bike'),T('আজ কী করতে হবে, দেখে নিন।','See what needs attention today.'))}${bikeCard()}${state.documents.some(d=>d.expiry&&days(d.expiry)<=30)?notice(T('ট্যাক্স টোকেনের মেয়াদ কাছাকাছি','A document needs attention'),T('নমুনা ট্যাক্স টোকেনের মেয়াদ শেষ হতে আর ৭ দিন।','The sample tax token expires in 7 days.'),'warning',`<button class="text-link" data-route="documents">${T('কাগজপত্র দেখুন','View documents')} →</button>`):notice(T('সবকিছু এক জায়গায়','Everything in one place'),T('তথ্য যোগ করলে এখানেই প্রয়োজনীয় কাজ দেখবেন।','Add your records to see useful next steps here.'))}<div><div class="section-heading"><h2>${T('দ্রুত যোগ করুন','Quick entry')}</h2></div><div class="quick-actions">${btn(`<span class="symbol" aria-hidden="true">＋</span>${T('তেল ভরার হিসাব','Fuel fill-up')}`,'fuel')}${btn(`<span class="symbol" aria-hidden="true">⌁</span>${T('সার্ভিস','Service')}`,'service','secondary')}</div></div><div class="metrics"><div class="metric"><span>${T('মিটারের রিডিং','Meter reading')}</span><strong>${n(state.odometer)}</strong><span>${T('কিমি','km')}</span></div><div class="metric"><span>${T('নমুনা মাসের খরচ','Sample month expenses')}</span><strong>${money(state.logs.reduce((a,l)=>a+l.cost,0))}</strong><span>${T('তেল ও সার্ভিস','Fuel and service')}</span></div></div><section><div class="section-heading"><h2>${T('সার্ভিসের সময়','Service timing')}</h2><button class="text-link" data-route="components">${T('সব দেখুন','View all')} →</button></div>${state.baselineKnown?maintenanceRows():notice(T('আগের সার্ভিসের তথ্য যোগ করুন','Add your service baseline'),T('তথ্য না জানা থাকলে আন্দাজ দেখাব না। চাইলে এখন সময়সূচি ঠিক করুন।','No guessed health score. Add a baseline when you know it.'),'',`<button class="text-link" data-route="schedule">${T('সময় ঠিক করুন','Set schedule')} →</button>`)}</section><button class="text-link" data-route="settings">${T('ভাষা, থিম ও সেটিংস','Language, theme & settings')} →</button>`,
 fuel:()=>entryForm('fuel'), service:()=>entryForm('service'),
 components:()=>`${head(T('সার্ভিসের সময়সূচি','Service schedules'),T('সময় বা দূরত্ব, যেটি আগে পূর্ণ হয়। এটি বাইকের অবস্থা পরীক্ষা করে না।','Time or distance, whichever comes first. This does not measure mechanical condition.'),'garage')}${state.baselineKnown?maintenanceRows():notice(T('আগের তথ্য এখনো দেওয়া হয়নি','Baseline not entered'),T('শেষ সার্ভিসের তথ্য দিলে পরের সময় দেখাতে পারব।','Add the last service details to estimate what comes next.'))}${state.schedules.map(s=>`<button class="card clickable" data-schedule="${s.id}"><div class="row between"><strong>${componentName(s.id)}</strong><span aria-hidden="true">→</span></div><p class="meta">${T('প্রতি','Every')} ${n(s.km)} ${T('কিমি বা','km or')} ${n(s.days)} ${T('দিন','days')}</p></button>`).join('')}${notice(T('মোটরসাইকেলের ম্যানুয়াল দেখুন','Check your motorcycle manual'),T('নমুনা সময়সূচি প্রস্তুতকারকের পরামর্শ নয়। নিজের ম্যানুয়াল বা মেকানিকের পরামর্শ অনুযায়ী ঠিক করুন।','Sample schedules are not manufacturer guidance. Set them using your manual or mechanic’s advice.'))}`,
 schedule:()=>{const s=state.schedules.find(s=>s.id===selectedComponent)||state.schedules[0];return `${head(T('সার্ভিসের সময় ঠিক করুন','Set service timing'),componentName(s.id),'components')}<form id="schedule-form" class="form" novalidate>${field('interval-km',T('কত কিমি পরপর','Distance interval (km)'),s.km,'text')}${field('interval-days',T('কত দিন পরপর','Time interval (days)'),s.days,'text')}${check('known-baseline',T('শেষ সার্ভিসের তথ্য জানি','I know the last service details'),s.known,T('না জানা থাকলে বন্ধ রাখুন।','Leave off if you do not know.'))}<div id="baseline-fields" class="stack" ${s.known?'':'hidden'}>${field('baseline-odo',T('শেষ সার্ভিসের রিডিং','Last service reading'),s.lastOdo,'text','',false)}${field('baseline-date',T('শেষ সার্ভিসের তারিখ','Last service date'),s.lastDate,'date','',false)}</div>${formError()}<button class="button full">${T('সময়সূচি সেভ করুন','Save schedule')}</button></form>`;},
 history:()=>`${head(T('আগের রেকর্ড','Your records'),T('তেল ও সার্ভিসের হিসাব। ভুল হলে এখানেই ঠিক করুন।','Fuel and service records. Correct a mistake here.'))}<div class="button-row">${btn(T('তেলের হিসাব','Add fuel'),'fuel')}${btn(T('সার্ভিস','Add service'),'service','secondary')}</div><div class="segmented" aria-label="${T('রেকর্ড বাছাই','Filter records')}">${[['all',T('সব','All')],['fuel',T('তেল','Fuel')],['service',T('সার্ভিস','Service')]].map(([key,label])=>`<button data-filter="${key}" aria-pressed="${filter===key}">${label}</button>`).join('')}</div>${field('history-search',T('রেকর্ড খুঁজুন','Search records'),'','search',T('তারিখ, নোট বা সার্ভিসের নাম লিখুন।','Search date, note or service name.'),false)}<div id="history-results">${historyRows()}</div>${btn(T('সার্ভিসের সারাংশ দেখুন','Review service summary'),'passport','secondary full')}`,
 documents:()=>`${head(T('কাগজপত্র','Documents'),T('প্রয়োজনীয় কাগজ সহজে খুঁজে পান।','Find your documents quickly.'))}<div class="button-row">${btn(T('কাগজ যোগ করুন','Add document'),'capture')}${btn(T('দেখান','Show documents'),'inspection','secondary')}</div>${state.documents.length?`<div class="record-list">${state.documents.map(d=>`<button class="card clickable" style="margin-bottom:12px" data-document="${d.id}"><div class="row start"><span class="record-icon" aria-hidden="true">▤</span><div class="grow"><h3>${docName(d.type)}</h3><p class="meta">${esc(d.number)}</p><p class="meta">${d.expiry?date(d.expiry):T('মেয়াদ দেওয়া নেই','No expiry entered')}</p></div><span aria-hidden="true">→</span></div><div style="margin-top:12px">${docStatus(d)}</div></button>`).join('')}</div>`:`<div class="empty"><span class="empty-icon" aria-hidden="true">▤</span><h2>${T('কাগজপত্র যোগ করে রাখুন','Keep your documents together')}</h2><p>${T('রেজিস্ট্রেশন, ট্যাক্স টোকেন বা লাইসেন্স দিয়ে শুরু করুন।','Start with registration, a tax token or licence.')}</p></div>`}<button class="card clickable" data-route="reminders"><div class="row between"><div><h3>${T('মেয়াদের মনে করিয়ে দেওয়া','Expiry reminders')}</h3><p class="meta">${state.reminders?T('চালু আছে','Enabled'):T('আপনার ইচ্ছায় চালু হবে','Off until you choose')}</p></div><span aria-hidden="true">→</span></div></button><p class="help">${T('মেয়াদের হিসাব আপনার দেওয়া তারিখ থেকে। কাগজের সত্যতা যাচাই করা হয় না।','Expiry status uses your entered dates. It does not verify authenticity.')}</p>`,
 capture:()=>`${head(T('কাগজ যোগ করুন','Add a document'),T('পরিষ্কার ছবি বা PDF বাছুন। আসল ফাইল বদলানো হবে না।','Choose a clear image or PDF. Keep the original unchanged.'),'documents')}<form id="capture-form" class="form">${select('document-type',T('কোন কাগজ?','Document type'),[['tax',docName('tax')],['registration',docName('registration')],['licence',docName('licence')],['insurance',docName('insurance')]],draft?.type||'tax')}<div class="upload-area"><span class="empty-icon" aria-hidden="true">▤</span><strong>${T('ছবি বা PDF বাছুন','Choose image or PDF')}</strong><label for="document-file" class="help">${T('JPG, PNG, WebP বা PDF · সর্বোচ্চ ৫ MB','JPG, PNG, WebP or PDF · up to 5 MB')}</label><input type="file" id="document-file" accept="image/jpeg,image/png,image/webp,application/pdf"><span id="document-file-error" class="field-error" role="alert"></span></div>${notice(T('ছবি তোলার সময়','When taking a photo'),T('পুরো কাগজটি রাখুন। ঝাপসা বা আলো বেশি হলে আবার তুলুন। চাইলে পরে নিজেই তথ্য লিখতে পারবেন।','Include the whole document. Retake if blurred or too bright. You can enter details manually.'))}<div class="prototype-label">${T('এখানে ক্যামেরা বা অটো লেখা পড়া চালু নেই। বাছাই করা ফাইল শুধু এই ব্রাউজারে দেখানো হবে।','Camera and OCR are not active here. Selected files stay in this browser preview.')}</div>${formError()}<button class="button full" type="submit">${T('তথ্য দেখে নিই','Review details')}</button><button class="button secondary full" type="button" id="use-sample">${T('নমুনা দিয়ে দেখি','Try a sample document')}</button></form>`,
 review:()=>{const d=draft||{type:'tax',sample:true};return `${head(T('তথ্য মিলিয়ে নিন','Check the details'),T('কাগজের সঙ্গে মিলিয়ে নাম, নম্বর ও তারিখ লিখুন।','Compare with the document and enter name, number and dates.'),'capture')}${sampleDocument(d)}<div class="review-tools"><button class="button secondary" id="rotate-preview">${T('ছবি ঘোরান','Rotate preview')}</button><button class="button secondary" data-route="capture">${T('ফাইল বদলান','Choose another file')}</button></div><p class="help">${T('প্রিভিউ ঘোরালেও আসল ফাইল বদলায় না। এখানে স্বয়ংক্রিয় লেখা পড়া হয় না।','Rotating this preview does not change the original. No automatic text reading in this prototype.')}</p><form id="review-form" class="form" novalidate>${field('doc-number',T('কাগজের নম্বর','Document number'),d.number||'')}${field('doc-holder',T('নাম','Holder name'),d.holder||'')}${field('doc-issued',T('ইস্যুর তারিখ','Issue date'),d.issued||'','date','',false)}${field('doc-expiry',T('মেয়াদ শেষের তারিখ','Expiry date'),d.expiry||'','date',T('মেয়াদ না থাকলে খালি রাখুন।','Leave blank if there is no expiry.'),false)}${check('doc-confirm',T('কাগজের সঙ্গে তথ্য মিলিয়ে দেখেছি','I checked these details against the document'))}${formError()}<button class="button full">${T('কাগজপত্র সেভ করুন','Save document')}</button></form>`;},
 document:()=>{const d=state.documents.find(d=>d.id===selectedDoc)||state.documents[0];if(!d)return `${head(T('কাগজ পাওয়া যায়নি','Document not found'),'','documents')}${btn(T('কাগজ যোগ করুন','Add document'),'capture')}`;return `${head(docName(d.type),'','documents')}${docStatus(d)}${sampleDocument(d)}<dl class="detail-list"><div class="wide"><dt>${T('কাগজের নম্বর','Document number')}</dt><dd>${esc(d.number)}</dd></div><div class="wide"><dt>${T('নাম','Holder')}</dt><dd>${esc(d.holder)}</dd></div><div><dt>${T('ইস্যুর তারিখ','Issued')}</dt><dd>${d.issued?date(d.issued):T('দেওয়া নেই','Not entered')}</dd></div><div><dt>${T('মেয়াদ','Expiry')}</dt><dd>${date(d.expiry)}</dd></div></dl><div class="button-row">${btn(T('দেখান','Show document'),'inspection')}<button class="button secondary" id="edit-document">${T('তথ্য ঠিক করুন','Edit details')}</button></div><button class="button secondary full" id="open-original">${T('আসল ফাইল দেখুন','View original file')}</button>${notice(T('এই ফোনের তথ্য','Local document'),T('তারিখ ও নাম আপনার দেওয়া। এটি সরকারি যাচাই নয়।','Names and dates are owner-entered. This is not official verification.'))}<button class="text-link" id="delete-document">${T('কাগজটি সরিয়ে দিন','Remove document')}</button>${formError()}`;},
 inspection:()=>{const d=state.documents.find(d=>d.id===selectedDoc)||state.documents[0];return `${head(T('কাগজপত্র দেখান','Show documents'),'','documents')}${state.documents.length?`<div class="segmented">${state.documents.map(item=>`<button data-inspect="${item.id}" aria-pressed="${d?.id===item.id}">${docName(item.type)}</button>`).join('')}</div><h2>${docName(d.type)}</h2>${sampleDocument(d)}<div class="card"><p>${T('নম্বর','Number')}: <strong>${esc(d.number)}</strong></p><p>${T('মেয়াদ','Expiry')}: ${date(d.expiry)}</p></div><button class="button secondary full" id="open-original">${T('আসল ফাইল দেখুন','View original file')}</button>`:`<div class="empty"><h2>${T('আগে কাগজ যোগ করুন','Add a document first')}</h2>${btn(T('কাগজ যোগ করুন','Add document'),'capture')}</div>`}<p class="help">${T('প্রয়োজনে আসল কাগজ সঙ্গে রাখুন। এই ভিউতে বাইকের খরচ বা সার্ভিসের হিসাব দেখানো হয় না।','Carry original documents when required. This view excludes fuel and service records.')}</p>`;},
 passport:()=>`${head(T('সার্ভিসের সারাংশ','Service summary'),T('শেয়ার করার আগে কী থাকবে দেখে নিন।','Review what is included before sharing.'),'history')}${bikeCard()}<div class="card stack"><h2>${T('যা থাকবে','Included')}</h2><p>✓ ${T('বাইকের নাম ও মিটারের রিডিং','Motorcycle and current reading')}</p><p>✓ ${T('সার্ভিসের তারিখ, খরচ ও নোট','Service dates, expenses and notes')}</p><p>✓ ${T('আপনার দেওয়া তথ্যের কথা স্পষ্ট থাকবে','Explicitly marked as owner-entered')}</p><hr><p class="meta">${T('কাগজপত্রের ছবি, ব্যক্তিগত কাগজের নম্বর ও তেলের রেকর্ড থাকবে না।','Document images, document identifiers and fuel records are excluded.')}</p></div>${notice(T('ব্যক্তিগত রেকর্ডের সারাংশ','Personal record summary'),T('এটি সরকারি প্রমাণ, মেকানিকের সার্টিফিকেট বা পুরো অ্যাপের ব্যাকআপ নয়।','Not official proof, a mechanic certificate or a full app backup.'))}${formError()}<button class="button full" id="download-summary">${T('সারাংশ ডাউনলোড করুন','Download summary')}</button><p class="help">${T('এই প্রোটোটাইপে নমুনা সারাংশ লেখা ফাইল হিসেবে নামবে। PDF নয়।','This prototype downloads a sample text summary, not a PDF.')}</p>`,
 settings:()=>`${head(T('সেটিংস','Settings'),T('আপনার মতো করে ব্যবহার করুন।','Make it comfortable for you.'),'garage')}<section><h2>${T('ভাষা','Language')}</h2><div class="segmented" style="margin-top:12px"><button data-language="bn" aria-pressed="${state.language==='bn'}">বাংলা</button><button data-language="en" aria-pressed="${state.language==='en'}">English</button></div></section><section><h2>${T('থিম','Appearance')}</h2><div class="segmented" style="margin-top:12px"><button data-theme-choice="light" aria-pressed="${state.theme==='light'}">${T('হালকা','Light')}</button><button data-theme-choice="dark" aria-pressed="${state.theme==='dark'}">${T('গাঢ়','Dark')}</button></div></section><section><h2>${T('ব্র্যান্ডের রং','Brand accent')}</h2><div class="segmented" style="margin-top:12px"><button data-accent="yamaha" aria-pressed="${state.brand==='yamaha'}">Yamaha</button><button data-accent="ktm" aria-pressed="${state.brand==='ktm'}">KTM</button><button data-accent="cfmoto" aria-pressed="${state.brand==='cfmoto'}">CFMOTO</button></div></section><div class="record-list"><button class="card clickable" data-route="reminders"><div class="row between"><h3>${T('মেয়াদের মনে করিয়ে দেওয়া','Expiry reminders')}</h3><span>→</span></div></button></div>${notice(T('এই ব্রাউজারে সেভ আছে','Stored in this browser'),T('এটি নমুনা ডেটা। ব্রাউজারের ডেটা মুছলে হারিয়ে যাবে। আসল অ্যাপের নিরাপদ ব্যাকআপ ও রিকভারি আলাদাভাবে তৈরি করতে হবে।','This is sample data. Clearing browser data removes it. Secure backup and recovery must be built separately in the native app.'))}<details><summary>${T('ফোন হারালে কী হবে?','What if I lose my phone?')}</summary><p>${T('শুধু ফোনে থাকা তথ্য অন্য ফোনে নিজে থেকে আসবে না। এই প্রোটোটাইপে ক্লাউড ব্যাকআপ নেই। সার্ভিসের সারাংশ পুরো ডেটার ব্যাকআপ নয়।','Local-only records do not appear automatically on another phone. No cloud backup exists in this prototype. A service summary is not a full backup.')}</p></details>`,
 reminders:()=>`${head(T('মেয়াদ মনে করিয়ে দিন','Expiry reminders'),T('আপনি চালু করলেই মনে করিয়ে দেওয়া হবে।','Reminders only after you choose to enable them.'),'documents')}<div class="card"><div class="setting-row"><label for="reminder-switch"><strong>${T('মনে করিয়ে দেওয়া','Reminders')}</strong><p>${T('মেয়াদ শেষ হওয়ার ৭ দিন আগে','7 days before expiry')}</p></label><input type="checkbox" class="switch" id="reminder-switch" ${state.reminders?'checked':''}></div></div>${notice(T('নোটিফিকেশনের অনুমতি','Notification permission'),T('আসল অ্যাপে চালু করলে ফোনের অনুমতি চাইবে। এখানে শুধু নমুনা পছন্দ সেভ হবে, নোটিফিকেশন পাঠানো হবে না।','The native app will request OS permission when enabled. This preview saves a sample preference only; it sends no notification.'))}<div class="prototype-label"><p>${T('অনুমতি না থাকলে যেভাবে দেখাবে','Permission-denied example')}</p><p>${T('নোটিফিকেশন বন্ধ আছে। ফোনের সেটিংস থেকে অনুমতি দিলে মনে করিয়ে দেওয়া যাবে।','Notifications are off. Allow them in phone settings to receive reminders.')}</p></div>${formError()}`,
 recovery:()=>`${head(T('আগের তথ্য খুলতে পারছি না','Your records could not be opened'),T('নতুন বাইক তৈরি করার আগে সমস্যাটি ঠিক করা দরকার।','Resolve this before creating a new garage.'))}${notice(T('আগের তথ্য মুছবেন না','Keep the existing data'),T('পড়া যায়নি মানেই তথ্য নেই, এমন নয়। আবার চেষ্টা করুন। না হলে কীভাবে উদ্ধার করা যায় দেখুন।','Unreadable does not mean empty. Retry first, then check recovery options.'),'error')}${formError()}<button class="button full" id="retry-restore">${T('আবার চেষ্টা করুন','Try again')}</button><details><summary>${T('তথ্য উদ্ধারের উপায়','Recovery guidance')}</summary><p>${T('আসল অ্যাপে পুরোনো ফাইল অক্ষত রেখে সহায়তা ও ব্যাকআপ থেকে ফেরানোর পথ দিতে হবে। এখানে রিকভারি স্ক্রিনের ডিজাইন দেখানো হচ্ছে।','The native app must preserve existing files and offer support or verified backup restoration. This is a design demonstration of that state.')}</p></details><button class="button secondary full" id="recovery-help">${T('সমস্যার তথ্য দেখুন','View diagnostic details')}</button>`,
 odometer:()=>`${head(T('মিটারের রিডিং','Meter reading'),T('এখন মিটারে যত কিমি দেখাচ্ছে, লিখুন।','Enter the current reading on your motorcycle.'),'garage')}<form id="odometer-form" class="form" novalidate>${field('current-odo',T('রিডিং (কিমি)','Reading (km)'),state.odometer,'text',T('রিডিং কমাতে হলে আগের ভুলটি ঠিক করার কারণ লিখুন।','To lower a mistaken reading, explain the correction.'))}${field('odo-note',T('সংশোধনের কারণ','Correction reason'),'','text','',false)}${formError()}<button class="button full">${T('রিডিং সেভ করুন','Save reading')}</button></form>`,
 saved:()=>`${head(T('সেভ হয়েছে','Saved'),T('তথ্য আপনার রেকর্ডে যোগ হয়েছে।','Your records have been updated.'))}${notice(T('সব ঠিক আছে','You are all set'),T('চাইলে রেকর্ড দেখুন বা বাইকের পাতায় ফিরে যান।','Review the record or return to your motorcycle.'),'success')}${btn(T('রেকর্ড দেখুন','View records'),'history','full')}${btn(T('আমার বাইকে ফিরি','Back to my bike'),'garage','secondary full')}`,
 camera:()=>`${head(T('পুরো কাগজটি রাখুন','Include the whole document'),T('লেখা পরিষ্কার দেখা যাচ্ছে কি না দেখুন।','Check that the text is clear.'),'capture')}<div class="camera-frame">${sampleDocument({type:'tax',sample:true})}</div>${notice(T('আলো বেশি হতে পারে','The image may be too bright'),T('কাগজটি একটু সরিয়ে দেখুন। পরিষ্কার দেখা গেলে এই ছবিও ব্যবহার করতে পারবেন।','Move the document slightly. If the text is clear, you can still use this image.'),'warning')}<button class="button full" id="capture-sample">${T('ছবি তুলুন','Capture photo')}</button><button class="button secondary full" data-route="capture">${T('ফাইল থেকে বাছুন','Choose a file instead')}</button><p class="prototype-label">${T('ক্যামেরার নমুনা ভিউ। আসল ক্যামেরা চালু হবে না।','Simulated camera view. No camera access is requested.')}</p>`,
 crop:()=>`${head(T('কাগজের সীমানা ঠিক করুন','Adjust document edges'),T('লেখা যেন বাদ না যায়। চাইলে পুরো ছবিই রাখুন।','Keep all the text inside. You can keep the full image.'),'review')}<div class="crop-viewport"><div id="crop-content">${sampleDocument(draft||{type:'tax',sample:true})}</div></div><form id="crop-form" class="form">${[['top',T('ওপরের সীমানা','Top edge')],['right',T('ডানের সীমানা','Right edge')],['bottom',T('নিচের সীমানা','Bottom edge')],['left',T('বামের সীমানা','Left edge')]].map(([edge,label])=>`<div class="field"><label for="crop-${edge}">${label}</label><input id="crop-${edge}" type="range" min="0" max="20" value="${draft?.crop?.[edge]||0}" data-crop-edge="${edge}"><output id="crop-${edge}-value" for="crop-${edge}">${n(draft?.crop?.[edge]||0)}%</output></div>`).join('')}<p class="help">${T('সীমানার প্রিভিউ বদলাবে। আসল ফাইল বদলাবে না।','Only preview edges change. The original file stays unchanged.')}</p><button class="button full">${T('এই সীমানা রাখুন','Use these edges')}</button><button class="button secondary full" type="button" id="reset-crop">${T('পুরো ছবি রাখুন','Keep the full image')}</button></form>`
};
views.pages=()=>`${head(T('কাগজের পাতাগুলো','Document pages'),T('সামনে-পেছনে বা একাধিক পাতা থাকলে ক্রম মিলিয়ে রাখুন।','Keep front/back or multiple pages in the right order.'),'review')}<div class="stack">${(draft?.pages||[{label:T('সামনের পাতা','Front page')}]).map((page,index)=>`<div class="card"><div class="row between"><h3>${T('পাতা','Page')} ${n(index+1)}</h3>${badge(index===0?T('সামনের পাতা','Front page'):T('অতিরিক্ত পাতা','Additional page'))}</div><p class="meta">${T('নমুনা পাতার প্রিভিউ','Sample page preview')}</p><div class="button-row">${index?`<button class="text-link" data-move-page="${index}">${T('আগে আনুন','Move earlier')}</button>`:''}${index?`<button class="text-link" data-remove-page="${index}">${T('বাদ দিন','Remove')}</button>`:''}</div></div>`).join('')}</div><button class="button secondary full" id="add-sample-page">${T('আরেকটি নমুনা পাতা যোগ করুন','Add another sample page')}</button>${btn(T('তথ্য মিলিয়ে নিই','Review details'),'review','full')}<p class="help">${T('আসল অ্যাপে ছবি বাছা ও PDF পাতার সংখ্যা থেকে এই তালিকা হবে। এখানে ক্রম ও নিয়ন্ত্রণের নমুনা দেখানো হচ্ছে।','The native app will build this list from selected images or PDF pages. This sample demonstrates ordering controls.')}</p>`;
views.cameraDenied=()=>`${head(T('ক্যামেরার অনুমতি নেই','Camera permission is off'),T('ফাইল থেকে কাগজ যোগ করতে পারবেন।','You can still import a document file.'),'capture')}${notice(T('আপনার পছন্দ','Your choice'),T('ক্যামেরা ব্যবহার করতে চাইলে ফোনের সেটিংস থেকে অনুমতি দিন। না চাইলে ছবি বা PDF বাছুন।','Allow camera access in phone settings if you want to take a photo. Otherwise choose an image or PDF.'))}${btn(T('ফাইল থেকে বাছুন','Choose a file'),'capture','full')}<button class="button secondary full" id="camera-settings-help">${T('ফোনের সেটিংস','Phone settings')}</button>`;
views.original=()=>{const d=state.documents.find(d=>d.id===selectedDoc)||state.documents[0];return `${head(T('আসল ফাইল','Original file'),T('প্রিভিউতে তথ্য বদলালেও আসল ফাইল বদলাবে না।','Editing record details does not change the original.'),'document')}${d?`<div class="segmented">${(d.pages||[{label:'1'}]).map((page,index)=>`<button data-original-page="${index}" aria-pressed="${index===0}">${T('পাতা','Page')} ${n(index+1)}</button>`).join('')}</div><p class="original-page-label meta">${d.sample?T('নমুনা পাতা ১','Sample page 1'):esc(d.fileName||'')}</p><div class="original-viewer" id="original-viewer">${sampleDocument(d)}</div><button class="button secondary full" id="original-zoom" aria-pressed="false">${T('বড় করে দেখুন','Enlarge preview')}</button><button class="button full" id="open-original">${T('আসল ফাইল ডাউনলোড করুন','Download original')}</button><p class="help">${T('এখানে PDF-এর আসল পাতাগুলো আঁকা হয় না। PDF বাছলে ফাইল ডাউনলোড করে নিজের ভিউয়ারে খুলুন।','This prototype does not render PDF pages. Download a selected PDF and open it in your viewer.')}</p>`:notice(T('ফাইল নেই','No file'),T('আগে একটি কাগজ যোগ করুন।','Add a document first.'))}`;};
function modelChoices(query=''){const models=setupDraft.brand==='ktm'?['Duke 125']:setupDraft.brand==='cfmoto'?['250NK']:setupDraft.brand==='yamaha'?['MT-15 V2','R15 V4']:[];const matched=models.filter(m=>m.toLowerCase().includes(query.toLowerCase()));return matched.length?matched.map(m=>`<button class="card clickable bike-card" data-model="${m}" aria-pressed="${setupDraft.model===m}"><img class="bike-thumb" src="${imageFor(m)}" alt=""><div class="grow"><strong>${m}</strong><p class="meta">${setupDraft.model===m?T('বাছাই করা হয়েছে','Selected'):T('এই মডেল বাছুন','Choose this model')}</p></div>${setupDraft.model===m?'<span aria-hidden="true">✓</span>':''}</button>`).join(''):`<p class="help">${T('এই নমুনায় মডেলটি নেই। নিচে নাম লিখুন।','This sample catalogue has no match. Enter the model name below.')}</p>`;}
function maintenanceRows(){return `<div class="stack">${state.schedules.map(s=>{if(!s.known)return `<button class="card clickable" data-schedule="${s.id}"><div class="row between"><strong>${componentName(s.id)}</strong>${badge(T('তথ্য দরকার','Baseline needed'))}</div><p class="meta">${T('শেষ সার্ভিসের তথ্য দিন। না জানা থাকলে আন্দাজ দেখাব না।','Add the last service details. Unknown history stays unknown.')}</p></button>`;const remaining=Math.max(0,s.km-(state.odometer-s.lastOdo)),timeLeft=Math.max(0,s.days-daysSince(s.lastDate));const due=remaining===0||timeLeft===0;const soon=remaining<=s.km*.25||timeLeft<=7;return `<button class="card clickable" data-schedule="${s.id}"><div class="row between"><strong>${componentName(s.id)}</strong>${badge(due?T('সার্ভিসের সময় হয়েছে','Service due'):soon?T('সময় কাছাকাছি','Due soon'):T('সময় বাকি আছে','Not yet due'),due?'error':soon?'warning':'good')}</div><p class="meta" style="margin-top:8px">${T('আর প্রায়','About')} ${n(remaining)} ${T('কিমি বা','km or')} ${n(timeLeft)} ${T('দিন, যেটি আগে হয়','days, whichever comes first')}</p><div class="status-bar ${due?'error':soon?'warning':''}"><span style="width:${Math.min(100,remaining/s.km*100,timeLeft/s.days*100)}%"></span></div><p class="meta">${T('আপনার দেওয়া সময়সূচির হিসাব','Estimate from your schedule')}</p></button>`;}).join('')}</div>`;}
function daysSince(value){return Math.floor((Date.parse(DEMO_TODAY)-Date.parse(value))/86400000);}
function deriveBaselines(logs,affected){return state.schedules.map(s=>{if(!affected.includes(s.id))return s;const latest=logs.filter(l=>l.kind==='service'&&l.component===s.id).sort((a,b)=>b.date.localeCompare(a.date)||b.odo-a.odo)[0];return latest?{...s,lastOdo:latest.odo,lastDate:latest.date,known:true}:{...s,known:false};});}
function historyRows(query=''){const logs=state.logs.filter(l=>(filter==='all'||l.kind===filter)&&`${date(l.date)} ${l.note} ${componentName(l.component)} ${l.date}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));if(!logs.length)return `<div class="empty"><span class="empty-icon" aria-hidden="true">◷</span><h2>${T('এখনো কোনো রেকর্ড নেই','No matching records')}</h2><p>${T('ওপর থেকে তেলের হিসাব বা সার্ভিস যোগ করুন।','Use the actions above to add fuel or service.')}</p></div>`;return `<div class="record-list">${logs.map(l=>`<div class="record-row start"><span class="record-icon" aria-hidden="true">${l.kind==='fuel'?'＋':'⌁'}</span><div class="grow"><h3>${l.kind==='fuel'?T('তেল ভরা','Fuel fill-up'):componentName(l.component)}</h3><p>${date(l.date)} · ${n(l.odo)} ${T('কিমি','km')}</p><p>${l.kind==='fuel'?`${n(l.litres)} ${T('লিটার','litres')}`:esc(l.note)||T('সার্ভিসের রেকর্ড','Service record')}</p><button class="text-link" data-edit-log="${l.id}">${T('তথ্য ঠিক করুন','Edit record')}</button></div><strong class="currency">${money(l.cost)}</strong></div>`).join('')}</div>`;}
function entryForm(kind){const existing=editingLog&&state.logs.find(l=>l.id===editingLog&&l.kind===kind);const service=kind==='service';return `${head(existing?T('রেকর্ড ঠিক করুন','Correct record'):service?T('সার্ভিস যোগ করুন','Add service'):T('তেল ভরার হিসাব','Fuel fill-up'),service?T('সার্ভিসের রিডিং বেশি হলে বাইকের রিডিংও আপডেট হবে।','A higher service reading will update the motorcycle reading too.'):T('আজকের তেল ভরার হিসাব রাখুন।','Keep a record of this fill-up.'),'history')}<form id="entry-form" class="form" data-kind="${kind}" novalidate>${service?select('service-component',T('কী সার্ভিস করেছেন?','What was serviced?'),state.schedules.map(s=>[s.id,componentName(s.id)]),existing?.component||selectedComponent):''}${field('entry-odo',T('মিটারের রিডিং (কিমি)','Meter reading (km)'),existing?.odo??state.odometer,'text')}${field('entry-date',T('তারিখ','Date'),existing?.date||DEMO_TODAY,'date')}${service?'':field('entry-litres',T('কত লিটার','Litres added'),existing?.litres||'','text')}${field('entry-cost',T('মোট খরচ (টাকা)','Total cost (taka)'),existing?.cost||'','text')}${service?field('entry-note',T('নোট','Note'),existing?.note||'','text','',false):check('full-tank',T('ট্যাংক পুরো ভরেছি','Filled to a full tank'),existing?.full||false,T('মাইলেজ বুঝতে দুইবার পুরো ট্যাংক ভরার রেকর্ড দরকার।','Two full-tank records establish an economy cycle.'))}${formError()}<button class="button full">${existing?T('সংশোধন সেভ করুন','Save correction'):T('সেভ করুন','Save record')}</button>${existing?`<button type="button" id="delete-log" class="button secondary">${T('রেকর্ড মুছুন','Delete record')}</button>`:''}</form>`;}
function validNumber(id,{min=0,max=1e8}={}){const input=document.getElementById(id);const value=parseNumber(input.value);if(!input.value.trim()||!Number.isFinite(value)||value<min||value>max){showError(id+'-error',T('সঠিক সংখ্যা লিখুন।','Enter a valid number.'));return null;}return value;}
function validDate(id,required=true){const value=document.getElementById(id).value;if(!value&&!required)return '';if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||value>DEMO_TODAY){showError(id+'-error',T('আজ বা আগের একটি তারিখ বেছে নিন।','Choose today or an earlier date.'));return null;}return value;}
function applyAccent(){const dark=state.theme==='dark';const colors={ktm:dark?['#ff8c42','#382719']:['#aa4700','#fff0e5'],cfmoto:dark?['#69d2db','#19343a']:['#00717a','#e8f5f5'],yamaha:dark?['#88a8ff','#222e49']:['#315abe','#ebf0fc']};const [accent,soft]=colors[state.brand]||colors.yamaha;document.documentElement.style.setProperty('--accent',accent);document.documentElement.style.setProperty('--soft',soft);document.documentElement.style.setProperty('--focus',accent);}
