 document.getElementById('schedule-form')?.addEventListener('submit',e=>{e.preventDefault();clearErrors();const km=validNumber('interval-km',{min:1}),time=validNumber('interval-days',{min:1});const known=document.getElementById('known-baseline').checked;const odo=known?validNumber('baseline-odo'):0,day=known?validDate('baseline-date'):DEMO_TODAY;if([km,time,odo,day].includes(null))return;if(known&&odo>state.odometer){showError('baseline-odo-error',T('শেষ সার্ভিসের রিডিং বর্তমান রিডিংয়ের চেয়ে বেশি হতে পারে না।','Last service reading cannot exceed the current reading.'));return;}const schedules=state.schedules.map(s=>s.id===selectedComponent?{...s,km,days:time,lastOdo:odo,lastDate:day,known}:s);if(commit({...state,baselineKnown:schedules.some(s=>s.known),schedules})){navigate('components');toast(T('সময়সূচি সেভ হয়েছে','Schedule saved'));}});
